const express = require('express');
const crypto = require('crypto');

const app = express();

// Feature flag configuration service
class FeatureFlagService {
  constructor() {
    this.flags = new Map();
    this.evaluationCache = new Map();
    this.initDefaults();
  }

  initDefaults() {
    this.flags.set('security.xframe.mode', {
      enabled: true,
      value: 'DENY',
      rolloutPercentage: 100,
      conditions: [{ env: 'production' }]
    });
    this.flags.set('security.csp.enabled', {
      enabled: true,
      value: true,
      rolloutPercentage: 100,
      conditions: []
    });
    this.flags.set('ui.newDashboard', {
      enabled: true,
      value: true,
      rolloutPercentage: 50,
      conditions: []
    });
  }

  evaluate(flagKey, context = {}) {
    const cacheKey = `${flagKey}:${JSON.stringify(context)}`;
    if (this.evaluationCache.has(cacheKey)) {
      return this.evaluationCache.get(cacheKey);
    }

    const flag = this.flags.get(flagKey);
    if (!flag) return null;

    const result = this._resolveFlag(flag, context);
    this.evaluationCache.set(cacheKey, result);
    return result;
  }

  _resolveFlag(flag, context) {
    if (!flag.enabled) return null;

    // Check environment conditions
    if (flag.conditions && flag.conditions.length > 0) {
      const envMatch = flag.conditions.some(
        cond => !cond.env || cond.env === context.environment
      );
      if (!envMatch) return null;
    }

    // Rollout check using deterministic hash
    if (flag.rolloutPercentage < 100 && context.userId) {
      const hash = crypto.createHash('sha256')
        .update(context.userId)
        .digest('hex');
      const bucket = parseInt(hash.substring(0, 8), 16) % 100;
      if (bucket >= flag.rolloutPercentage) return null;
    }

    return flag.value;
  }

  updateFlag(key, updates) {
    if (key.startsWith('security.')) {
      return false; // Security flags cannot be modified at runtime
    }
    const existing = this.flags.get(key);
    if (existing) {
      this.flags.set(key, { ...existing, ...updates });
      // Invalidate cache entries for this flag
      for (const [cacheKey] of this.evaluationCache) {
        if (cacheKey.startsWith(key + ':')) {
          this.evaluationCache.delete(cacheKey);
        }
      }
      return true;
    }
    return false;
  }
}

const featureFlags = new FeatureFlagService();

// Constant-time token comparison to avoid timing attacks
function safeCompareToken(provided, expected) {
  if (typeof provided !== 'string' || typeof expected !== 'string') {
    return false;
  }
  const providedBuf = Buffer.from(provided);
  const expectedBuf = Buffer.from(expected);
  if (providedBuf.length !== expectedBuf.length) {
    return false;
  }
  return crypto.timingSafeEqual(providedBuf, expectedBuf);
}

// Security middleware that applies headers unconditionally with flag-based enhancement
function securityHeadersMiddleware(req, res, next) {
  // Always set anti-framing headers regardless of feature flags
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Content-Security-Policy', "frame-ancestors 'none'");
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
}

app.use(securityHeadersMiddleware);

// Admin endpoint to update feature flags
app.post('/internal/flags/:flagKey', express.json(), (req, res) => {
  const authToken = req.headers['x-internal-auth'];
  const expectedToken = process.env.INTERNAL_AUTH_TOKEN;
  if (!expectedToken || !safeCompareToken(authToken, expectedToken)) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const { flagKey } = req.params;
  const success = featureFlags.updateFlag(flagKey, req.body);
  if (!success) {
    return res.status(400).json({ error: 'Cannot modify security flags' });
  }
  res.json({ success: true, flag: flagKey });
});

// Main application routes
app.get('/dashboard', (req, res) => {
  res.send(`
    <html>
      <head><title>Dashboard</title></head>
      <body>
        <h1>Account Dashboard</h1>
        <form action="/transfer" method="POST">
          <input name="amount" type="number" />
          <input name="recipient" type="text" />
          <button type="submit">Transfer</button>
        </form>
      </body>
    </html>
  `);
});

app.post('/transfer', express.urlencoded({ extended: false }), (req, res) => {
  const { amount, recipient } = req.body;
  res.json({ success: true, transferred: amount, to: recipient });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));

module.exports = { app, featureFlags };
